// 构建审批卡片内容
const input = $input.first().json;
const approvalId = input.approval_id || `apr_${Date.now()}`;
const reqType = input.request_type || input.workflow || 'unknown';
const title = input.title || input.workflow_name || '运维操作审批';
const content = input.content || JSON.stringify(input.params || {}, null, 2);
const callbackUrl = input.callback_url || 'http://localhost:7789/api/webhook/n8n_callback';
const cstTime = new Date().toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai' });

return {
  approval_id: approvalId,
  request_type: reqType,
  title: `🔐 审批请求: ${title}`,
  content: `类型: ${reqType}\n\n${content}\n\n时间: ${cstTime}`,
  callback_url: callbackUrl,
  require_role: input.require_role || 'admin',
  timestamp: cstTime,
  expires_in: 3600,
};
